+    // resulting MetaspaceSize matches the second MaxMetaspaceSize value.
+    testMaxMetaspaceSizeLTDefaultMetaspaceSizeTwice(LOWER_THAN_DEFAULT2,
+                                                    LOWER_THAN_DEFAULT1);
